import math

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n // 2:
        k = n - k
    return math.comb(n, k)

# Formula: C(N) = N/2 * (C(N-2, 2) - (N/2 - 1))
def calculate_C(N):
    if N % 2 != 0:
        return "N must be even for Perfect Matching structure"
    k = N // 2
    term1 = combinations(N - 2, 2)
    term2 = k - 1
    C_N = k * (term1 - term2)
    return C_N

N = 120
C_120 = calculate_C(N)

print(f"Calculated C({N}): {C_120}")
print(f"Expected value: 410640")
